require_once 'database.php';require_once 'functions.php';session_start();require_login();$me=user();$other=(int)($_GET['user']??$_POST['user']??0);$notice='';
if($other&&blocked_between($me['id'],$other))$other=0;
if($other&&!mutual($me['id'],$other))$other=0;
if($_SERVER['REQUEST_METHOD']==='POST'&&$other){check_csrf();if(isset($_POST['block'])){$q=$db->prepare("INSERT OR IGNORE INTO blocks(user_id,blocked_id) VALUES(?,?)");$q->execute([$me['id'],$other]);$db->prepare("DELETE FROM likes WHERE (user_id=? AND liked_user_id=?) OR (user_id=? AND liked_user_id=?)")->execute([$me['id'],$other,$other,$me['id']]);redirect('matches.php');}if(isset($_POST['report'])){$reason=trim($_POST['reason']??'');$details=trim($_POST['details']??'');$allowed=['Harassment or bullying','Spam or scam','Inappropriate content','Impersonation','Other'];if(!in_array($reason,$allowed,true))$reason='Other';$q=$db->prepare("INSERT INTO reports(reporter_id,reported_id,reason,details) VALUES(?,?,?,?)");$q->execute([$me['id'],$other,$reason,substr($details,0,2000)]);$notice='Report submitted to the moderation team.';}if(isset($_POST['send'])){$body=trim($_POST['body']??'');if($body!==''&&strlen($body)<=2000){$q=$db->prepare("INSERT INTO messages(sender_id,receiver_id,body) VALUES(?,?,?)");$q->execute([$me['id'],$other,$body]);redirect('messages.php?user='.$other);}}}
layout_start('Messages');$q=$db->prepare("SELECT DISTINCT u.id,u.username FROM users u JOIN likes l ON l.liked_user_id=u.id WHERE l.user_id=? AND EXISTS(SELECT 1 FROM likes l2 WHERE l2.user_id=u.id AND l2.liked_user_id=?) AND NOT EXISTS(SELECT 1 FROM blocks b WHERE (b.user_id=? AND b.blocked_id=u.id) OR (b.user_id=u.id AND b.blocked_id=?))");$q->execute([$me['id'],$me['id'],$me['id'],$me['id']]);$matches=$q->fetchAll(PDO::FETCH_ASSOC);echo '<div class="columns"><aside class="card"><h2>Matches</h2>';foreach($matches as $m)echo '<a class="conversation" href="messages.php?user='.$m['id'].'">'.h($m['username']).'</a>';echo '</aside><section class="card chat">';if($other){$q=$db->prepare("SELECT username FROM users WHERE id=?");$q->execute([$other]);$name=$q->fetchColumn();echo '<div class="chat-head"><div><h2>Chat with '.h($name).'</h2>'.($notice?'<p class="success">'.h($notice).'</p>':'').'</div><div class="action-row"><form method="post"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="user" value="'.$other.'"><button class="ghost" name="block">⛔ Block</button></form></div></div><details class="report"><summary>⚑ Report this person</summary><form method="post" class="report-form"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="user" value="'.$other.'"><label>Reason<select name="reason"><option>Harassment or bullying</option><option>Spam or scam</option><option>Inappropriate content</option><option>Impersonation</option><option>Other</option></select></label><label>Details<textarea name="details" maxlength="2000"></textarea></label><button class="danger" name="report">Submit report</button></form></details>';$q=$db->prepare("SELECT m.*,u.username FROM messages m JOIN users u ON u.id=m.sender_id WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) ORDER BY m.id");$q->execute([$me['id'],$other,$other,$me['id']]);foreach($q as $m)echo '<div class="bubble '.($m['sender_id']==$me['id']?'mine':'').'">'.'<b>'.h($m['username']).'</b><br>'.nl2br(h($m['body'])).'</div>';echo '<form method="post"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="user" value="'.$other.'"><textarea name="body" maxlength="2000" placeholder="Write a message..." required></textarea><button class="btn" name="send">Send</button></form>';}else echo '<p class="muted">Choose a mutual match to start messaging.</p>';echo '</section></div>';layout_end();
